/**
 * Harness page — runs hand-authored CompiledPlans through the real executor.
 * Fixtures are fetched over HTTP (generated by run.mjs into harness/
 * fixtures/, served by the package's vite host). The Node driver calls
 * __cases() / __runCase().
 */

import {
  execute, executePipeline, probe, plan, factsFromProbe, imageFacts, timedTextFacts,
  type AssetTable, type Backend, type DeriverBackends, type MediaFacts, type FactsTable,
} from '@katana-video/carrot';
import { CASES, FIXTURES } from './cases';
import { DOC_CASES } from './doc-cases';

// registered by backends-entry.ts (loaded first; see index.html)
const tier1Derivers = (): DeriverBackends =>
  (window as { __tier1Derivers?: DeriverBackends }).__tier1Derivers ?? {};

const statusEl = document.getElementById('status')!;
const log = (m: string) => { statusEl.textContent += m + '\n'; };

const blobCache = new Map<string, Promise<Blob>>();
function fixtureBlob(file: string): Promise<Blob> {
  let p = blobCache.get(file);
  if (!p) {
    p = fetch(`/harness/fixtures/${file}`).then(async (r) => {
      if (!r.ok) throw new Error(`fixture ${file}: HTTP ${r.status}`);
      return r.blob();
    });
    blobCache.set(file, p);
  }
  return p;
}

async function assetsFor(planAssets: Set<string>): Promise<AssetTable> {
  const table: AssetTable = {};
  await Promise.all([...planAssets].map(async (id) => {
    const fx = FIXTURES[id];
    if (!fx) throw new Error(`case references unknown fixture asset '${id}'`);
    table[id] = { kind: fx.kind, source: await fixtureBlob(fx.file), label: fx.file };
  }));
  return table;
}

function assetsReferenced(caseName: string): Set<string> {
  const c = CASES.find((x) => x.name === caseName)!;
  const ids = new Set<string>();
  for (const span of c.plan.spans) {
    for (const b of span.video?.bindings ?? []) ids.add(b.asset);
    for (const b of span.audio?.bindings ?? []) ids.add(b.asset);
    for (const id of Object.values(span.video?.staticSlots ?? {})) ids.add(id);
  }
  return ids;
}

interface RunResult {
  ok: boolean;
  error?: string;
  url?: string;
  bytes?: number;
  ms?: number;
  videoCodec?: string | null;
  audioCodec?: string | null;
}

declare global {
  interface Window {
    __cases(): { name: string; hasVideo: boolean; container: string; expected: unknown }[];
    __runCase(name: string, backend: Backend | 'auto'): Promise<RunResult>;
    __probe(fixtureFile: string): Promise<MediaFacts | { error: string }>;
  }
}

declare global {
  interface Window {
    __docCases(): { name: string; expected: unknown }[];
    __runDocument(name: string, backend: Backend | 'auto'): Promise<RunResult>;
  }
}

window.__docCases = () => DOC_CASES.map((c) => ({ name: c.name, expected: c.expected }));

window.__runDocument = async (name, backend) => {
  const c = DOC_CASES.find((x) => x.name === name);
  if (!c) return { ok: false, error: `unknown doc case '${name}'` };
  const t0 = performance.now();
  try {
    // assets + facts from the real probe (its first end-to-end use)
    const assetIds = Object.keys((c.document as { assets: Record<string, { kind: string }> }).assets);
    const table: AssetTable = {};
    const facts: FactsTable = {};
    for (const id of assetIds) {
      const fx = FIXTURES[id];
      if (!fx) return { ok: false, error: `doc case references unknown fixture '${id}'` };
      const blob = await fixtureBlob(fx.file);
      table[id] = { kind: fx.kind, source: blob, label: fx.file };
      if (fx.kind === 'image') {
        const bmp = await createImageBitmap(blob);
        facts[id] = imageFacts(bmp.width, bmp.height);
        bmp.close();
      } else if (fx.kind === 'timed-text') {
        facts[id] = timedTextFacts();
      } else {
        facts[id] = factsFromProbe(await probe(blob));
      }
    }
    const compiled = plan(c.document, facts);
    if (!compiled.pipeline) {
      const msg = compiled.errors.map((e) => `${e.code}@${e.path}`).join('; ');
      log(`❌ ${name} plan: ${msg}`);
      return { ok: false, error: `plan: ${msg}` };
    }
    const result = await executePipeline(compiled.pipeline, table, {
      backend, derivers: tier1Derivers(),
      onStep: (p) => log(`   ${name}: step ${p.stepIndex + 1}/${p.stepCount} ${p.kind} '${p.stepId}'`),
    });
    const url = URL.createObjectURL(result.blob!);
    const ms = Math.round(performance.now() - t0);
    log(`✅ ${name} [${backend}] ${result.blob!.size}B in ${ms}ms (${compiled.pipeline.steps.length} steps)`);
    return { ok: true, url, bytes: result.blob!.size, ms, videoCodec: result.videoCodec, audioCodec: result.audioCodec };
  } catch (err) {
    const msg = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
    log(`❌ ${name} [${backend}] ${msg}`);
    console.error(err);
    return { ok: false, error: msg };
  }
};

window.__probe = async (fixtureFile) => {
  try {
    return await probe(await fixtureBlob(fixtureFile));
  } catch (err) {
    return { error: err instanceof Error ? `${err.name}: ${err.message}` : String(err) };
  }
};

window.__cases = () => CASES.map((c) => ({
  name: c.name,
  hasVideo: !!c.plan.output.video,
  container: c.plan.output.container,
  expected: c.expected,
}));

window.__runCase = async (name, backend) => {
  const c = CASES.find((x) => x.name === name);
  if (!c) return { ok: false, error: `unknown case '${name}'` };
  const t0 = performance.now();
  try {
    const assets = await assetsFor(assetsReferenced(name));
    const result = await execute(c.plan, assets, { backend });
    const url = URL.createObjectURL(result.blob!);
    const ms = Math.round(performance.now() - t0);
    log(`✅ ${name} [${backend}] ${result.blob!.size}B in ${ms}ms`);
    return {
      ok: true, url, bytes: result.blob!.size, ms,
      videoCodec: result.videoCodec, audioCodec: result.audioCodec,
    };
  } catch (err) {
    const msg = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
    log(`❌ ${name} [${backend}] ${msg}`);
    console.error(err);
    return { ok: false, error: msg };
  }
};

log(`harness ready — ${CASES.length} cases`);
